<template><section><header class="page-head"><div><p class="eyebrow">PROFILE</p><h2>个人中心</h2></div></header><el-card v-if="user" class="profile-card"><AvatarUploader v-model="form.avatar" :fallback="user.nickname.slice(0,1)"/><el-form label-position="top"><el-form-item label="昵称"><el-input v-model="form.nickname"/></el-form-item><el-form-item label="楼栋 / 单元 / 房间"><div class="property"><el-input v-model="form.building" placeholder="楼栋"/><el-input v-model="form.unit" placeholder="单元"/><el-input v-model="form.room" placeholder="房间"/></div></el-form-item><el-button type="primary" @click="save">保存资料</el-button></el-form></el-card></section></template><script setup lang="ts">import{computed,reactive,watch}from'vue';import{ElMessage}from'element-plus';import{authStore}from'../stores/authStore';import{updateMe}from'../api/user';const user=computed(()=>authStore.user);const form=reactive({nickname:'',avatar:'',building:'',unit:'',room:''});watch(user,v=>{if(v)Object.assign(form,v)},{immediate:true});async function save(){try{const v=await updateMe(form);authStore.user=v;ElMessage.success('资料已保存')}catch(e){ElMessage.error((e as Error).message)}}</script>
